package main

import (
	"errors"
	"fmt"
	"time"

	"github.com/robertkrimen/otto"
)

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	var result []map[string]interface{}

	// Set a timeout to prevent Denial of Service (DoS) via infinite loops or heavy computation
	timeout := 100 * time.Millisecond

	for _, item := range items {
		// Creating a new VM per item prevents global state pollution and memory leaks 
		// that could be exploited by malicious scripts across iterations.
		vm := otto.New()
		vm.Interrupt = make(chan func(), 1)

		// Inject the current item as a global variable named 'item'
		err := vm.Set("item", item)
		if err != nil {
			return nil, err
		}

		// Timer to interrupt the VM if the script takes too long
		timer := time.AfterFunc(timeout, func() {
			vm.Interrupt <- func() {
				panic(errors.New("script execution timed out"))
			}
		})

		var value otto.Value
		var runErr error

		// Execute the script and safely recover from any panics (including timeouts)
		func() {
			defer func() {
				if r := recover(); r != nil {
					runErr = fmt.Errorf("script execution interrupted: %v", r)
				}
			}()
			value, runErr = vm.Run(conditionScript)
		}()

		// Stop the timer to prevent leaks
		timer.Stop()

		if runErr != nil {
			return nil, runErr
		}

		// Convert result to boolean using JavaScript truthiness
		boolResult, err := value.ToBoolean()
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}
	}

	return result, nil
}

