// runWithTimeout executes an Otto script in a separate goroutine and enforces a timeout.
// If the script takes longer than the specified duration, it triggers an interrupt to halt execution.
func runWithTimeout(vm *otto.Otto, script string, timeout time.Duration) (val otto.Value, err error) {
	done := make(chan struct{})

	go func() {
		defer func() {
			if r := recover(); r != nil {
				err = fmt.Errorf("script execution halted: %v", r)
			}
			close(done)
		}()
		val, err = vm.Run(script)
	}()

	select {
	case <-done:
		// Script finished within the time limit
		return val, err
	case <-time.After(timeout):
		// Timeout reached: inject a panic into the VM's execution thread to break infinite loops
		vm.Interrupt <- func() {
			panic("script execution timeout")
		}
		<-done // Wait for the goroutine to cleanly finish and recover
		return otto.UndefinedValue(), errors.New("script execution timeout: possible infinite loop or heavy computation")
	}
